using Application.Common.Exceptions; using Application.Common.Interfaces; using Application.Common.Interfaces.IService; using Application.Features.Premium.Freelancer.RankProtection.DTOs; using Application.Features.Premium.Freelancer.RankProtection.GetRankProtection; using Domain.Entities; using Domain.Enums; using MediatR; using Microsoft.EntityFrameworkCore;
namespace Application.Features.Premium.Freelancer.RankProtection.ActivateRankProtection;
public sealed class ActivateRankProtectionCommandHandler:IRequestHandler<ActivateRankProtectionCommand,RankProtectionDto>{private readonly IApplicationDbContext _context;private readonly IPremiumAccessService _premium;private readonly IDateTimeService _clock;private readonly ICacheService _cache;private readonly INotificationService _notifications;public ActivateRankProtectionCommandHandler(IApplicationDbContext c,IPremiumAccessService p,IDateTimeService d,ICacheService cache,INotificationService n){_context=c;_premium=p;_clock=d;_cache=cache;_notifications=n;}public async Task<RankProtectionDto> Handle(ActivateRankProtectionCommand c,CancellationToken ct){var benefits=await _premium.GetPremiumBenefitsAsync(c.UserId,ct);if(!benefits.IsPremium||benefits.PremiumUntil is null)throw new ForbiddenAccessException("An active Premium Freelancer subscription is required.");var now=_clock.UtcNow;var starts=c.Request.StartsAt??now;if(starts<now.AddMinutes(-1)||c.Request.EndsAt<=starts)throw new BadRequestException("Rank protection dates are invalid.");if(c.Request.EndsAt>benefits.PremiumUntil)throw new BadRequestException("Rank protection cannot extend beyond the subscription end.");var profileId=await _context.Set<FreelancerProfile>().Where(x=>x.UserId==c.UserId).Select(x=>(Guid?)x.FreelancerProfilesId).FirstOrDefaultAsync(ct)??throw new NotFoundException("Freelancer profile does not exist.");if(await _context.Set<FreelancerRankProtection>().AnyAsync(x=>x.FreelancerProfileId==profileId&&x.IsVacationModeEnabled&&x.CancelledAt==null&&x.RankProtectionStartedAt<c.Request.EndsAt&&x.RankProtectionEndsAt>starts,ct))throw new ConflictException("An active rank-protection window already overlaps this period.");var row=new FreelancerRankProtection{FreelancerRankProtectionsId=Guid.NewGuid(),FreelancerProfileId=profileId,IsVacationModeEnabled=true,RankProtectionStartedAt=starts,RankProtectionEndsAt=c.Request.EndsAt,RankProtectionReason=c.Request.Reason?.Trim(),CreatedAt=now};_context.Set<FreelancerRankProtection>().Add(row);await _context.SaveChangesAsync(ct);await _cache.RemoveAsync($"premium:rank-protection:{c.UserId:N}",ct);await _notifications.CreateNotificationAsync(c.UserId,NotificationType.RankProtectionActivated,"Vacation Mode activated",$"Your ranking is protected until {row.RankProtectionEndsAt:O}.",row.FreelancerRankProtectionsId,nameof(FreelancerRankProtection),ct);return RankProtectionMapper.Map(row);}}
